// Universal Product Text Sanitizer (cleans HTML entities, removes &; symbol artifacts, normalizes punctuation)
function sanitizeProductText(str) {
  if (!str || typeof str !== 'string') return '';
  return str
    // Decode Hexadecimal HTML entities (e.g. &#x1F470;)
    .replace(/&#x([0-9a-fA-F]+);/g, function(_, hex) {
      try {
        var code = parseInt(hex, 16);
        if (code > 0 && code <= 0x10FFFF) return String.fromCodePoint(code);
      } catch (e) {}
      return ' ';
    })
    // Decode Decimal HTML entities (e.g. &#128112;)
    .replace(/&#([0-9]+);/g, function(_, dec) {
      try {
        var code = parseInt(dec, 10);
        if (code > 0 && code <= 0x10FFFF) return String.fromCodePoint(code);
      } catch (e) {}
      return ' ';
    })
    // Decode standard named entities
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    // Permanently eliminate broken entity remnants (&; or &;&;&;)
    .replace(/(?:&;)+/g, ' ')
    .replace(/&[a-zA-Z0-9#_]+;/g, ' ')
    // Fix spacing before punctuation marks (e.g. "big day. &;&; Call" -> "big day. Call")
    .replace(/\s+([.,!?:])/g, '$1')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}

// Helper to get all items merging local storage additions with master catalog
function getUnifiedCatalog() {
  let customItems = [];
  try {
    customItems = JSON.parse(localStorage.getItem('custom_showcase_items') || '[]');
  } catch (e) {}

  // Merge dynamic items loaded from /api/catalog into custom items list
  if (typeof window !== 'undefined' && Array.isArray(window.LIVE_SERVER_CATALOG) && window.LIVE_SERVER_CATALOG.length > 0) {
    const knownIds = new Set(customItems.map(c => String(c.id)));
    for (const sItem of window.LIVE_SERVER_CATALOG) {
      if (sItem && sItem.id && !knownIds.has(String(sItem.id))) {
        customItems.push(sItem);
        knownIds.add(String(sItem.id));
      }
    }
  }

  let deletedIds = new Set();
  try {
    const rawDeleted = JSON.parse(localStorage.getItem('deleted_showcase_ids') || '[]');
    deletedIds = new Set(rawDeleted.map(String));
  } catch (e) {}

  let modifiedCustom = false;
  const activeCustom = customItems.filter(c => !deletedIds.has(String(c.id))).map(item => {
    let cleanDesc = item.description || '';
    let cleanTitle = item.title || '';
    let isFeatured = item.is_featured;
    let changed = false;

    // 1. Strip Instagram scraper prefix junk (e.g. '6 likes, 0 comments - sreedesigner_ on November 11, 2026: "')
    if (cleanDesc && /^\d+[\d,]*\s+likes?/i.test(cleanDesc)) {
      cleanDesc = cleanDesc.replace(/^\d+[\d,]*\s+likes?,\s*\d+[\d,]*\s+comments?\s*-\s*[^\n:]+:\s*["“]?/i, '');
      cleanDesc = cleanDesc.replace(/["”]?\s*$/, '').trim();
      changed = true;
    }

    // 2. Resolve title mismatch (e.g. 'Bridal Red' mistakenly assigned to Pastel Green blouse)
    const isGreenProduct = String(item.id) === 'prod-1794670454679' ||
                          (cleanDesc && /pastel green|pistachio|pista/i.test(cleanDesc)) ||
                          (item.main_image_url && /green/i.test(item.main_image_url));

    if (isGreenProduct && /bridal red|red blouse/i.test(cleanTitle)) {
      cleanTitle = 'Pastel Green Aari Work Blouse with Brocade Sleeves & Tie-Up Back';
      changed = true;
    }

    // 3. Resolve duplicate on homepage (keep prod-1793719000000 as the featured pastel green blouse)
    if (String(item.id) === 'prod-1794670454679' && isFeatured) {
      isFeatured = false;
      changed = true;
    }

    // 4. Sanitize entities & remove any '&;' symbol wreckage
    if (cleanDesc && (cleanDesc.includes('&;') || /&#[x0-9]/i.test(cleanDesc))) {
      cleanDesc = sanitizeProductText(cleanDesc);
      changed = true;
    }
    if (cleanTitle && (cleanTitle.includes('&;') || /&#[x0-9]/i.test(cleanTitle))) {
      cleanTitle = sanitizeProductText(cleanTitle);
      changed = true;
    }

    if (changed) {
      modifiedCustom = true;
      return Object.assign({}, item, {
        description: cleanDesc,
        title: cleanTitle,
        is_featured: isFeatured
      });
    }
    return item;
  });

  // Self-heal localStorage so old corrupted descriptions, mismatched titles, and duplicates are permanently repaired
  if (modifiedCustom) {
    try {
      localStorage.setItem('custom_showcase_items', JSON.stringify(activeCustom));
    } catch (e) {}
  }

  const customIds = new Set(activeCustom.map(c => String(c.id)));
  // Filter out any default items that are replaced by custom items OR were deleted
  const nonReplacedDefaults = MASTER_CATALOG.filter(d => !customIds.has(String(d.id)) && !deletedIds.has(String(d.id))).map(item => {
    if (item.description && item.description.includes('&;')) {
      return Object.assign({}, item, { description: sanitizeProductText(item.description) });
    }
    return item;
  });

  return [...activeCustom, ...nonReplacedDefaults];
}

if (typeof window !== 'undefined') {
  window.sanitizeProductText = sanitizeProductText;
  window.MASTER_CATALOG = MASTER_CATALOG;
  window.getUnifiedCatalog = getUnifiedCatalog;
}


